  ('ict-board-dhaka-2023-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p51', 'কম্পিউটারের এ অবস্থার জন্য নিচের কোনটি দায়ী হতে পারে?', 'mcq', '{"ক":"ভাইরাস","খ":"এন্টি ভাইরাস","গ":"সিস্টেম সফটওয়ার","ঘ":"এপ্লিকেশন সফটওয়্যার"}'::jsonb, 'ক', 1, false, 'ict-board-dhaka-2023-mcq', false, 'board-mcq', null, 'নাসিমা বেগম একটি বহুজাতিক কোম্পানিতে কম্পিউটার অপারেটর পদে চাকু রি করেন। একজন সহকর্মী তাঁর কম্পিউটার থেকে পেনড্রাইভের মাধ্যমে কিছু ফাইল কপি করে নেয়ার পর থেকে দেখলেন যে, তার কম্পিউটার হঠাৎ করে বন্ধ হয়ে যায় আবার চালু হয় এবং কম্পিউটারের গতিও কমে গেছে।', 'dhaka', 2023, true),
  ('ict-board-dhaka-2023-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p51', 'নাসিমার কম্পিউটারে যে সব সমস্যা দেখা যেতে পারে তা হল---- i. অপ্রত্যাশিত বার্তা প্রদর্শন করতে পারে ii. রাখা ফাইলগুলোর আকার বেড়ে যেতে পারে iii. মেমোরি কম দেখাতে পারে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-dhaka-2023-mcq', false, 'board-mcq', null, 'নাসিমা বেগম একটি বহুজাতিক কোম্পানিতে কম্পিউটার অপারেটর পদে চাকু রি করেন। একজন সহকর্মী তাঁর কম্পিউটার থেকে পেনড্রাইভের মাধ্যমে কিছু ফাইল কপি করে নেয়ার পর থেকে দেখলেন যে, তার কম্পিউটার হঠাৎ করে বন্ধ হয়ে যায় আবার চালু হয় এবং কম্পিউটারের গতিও কমে গেছে।', 'dhaka', 2023, true),
  ('ict-board-dhaka-2023-mcq-003', 'class9-ict-bn-guide', 'satt-ict-board.pdf p51', 'কম্পিউটারে সর্বপ্রথম কোন সফটওয়্যার ইনস্টল করতে হয়?', 'mcq', '{"ক":"অ্যাপ্লিকেশন প্রোগ্রাম","খ":"অপারেটিং সিস্টেম","গ":"অফিস সফটওয়্যার","ঘ":""}'::jsonb, 'খ', 1, false, 'ict-board-dhaka-2023-mcq', false, 'board-mcq', 'ঘ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'dhaka', 2023, true),
