  ('ict-board-dinajpur-2023-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p39', 'উপরোক্ত উদ্দেশ্য সাধনের জন্য জনাব হামিদা বেগম- i. ভিউ মেনুর স্লাইড শোতে ক্লিক করতে পারেন ii. ফাংশন কী এর F5 বাটনে ক্লিক করতে পারেন iii. স্ট্যাটাস বারের স্লাইড শো অপশনে ক্লিক করতে পারেন নিচের কোনটি সঠিক ?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-dinajpur-2023-mcq', false, 'board-mcq', null, 'জনাব হামিদা বেগম ১০ম শ্রেণির জীববিজ্ঞান বিষয়ের একটি পাওয়ার পয়েন্ট প্রেজেন্টেশন তৈরি করেন। তিনি স্লাইডসমূহ ঠিকঠাক মতো কাজ করে কিনা এবং যথাযথ হয়েছে কিনা তা পরীক্ষা করে নিতে চাইলেন।', 'dinajpur', 2023, true),
  ('ict-board-dinajpur-2023-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p39', '’স্লাইড শো'' থেকে এডিট উইন্ডোতে ফিরে যেতে হলে জনাব হামিদাকে নিচের কোন বাটনে ক্লিক করতে হবে ?', 'mcq', '{"ক":"Esc","খ":"Home","গ":"End","ঘ":"Backspace"}'::jsonb, 'ক', 1, false, 'ict-board-dinajpur-2023-mcq', false, 'board-mcq', null, 'জনাব হামিদা বেগম ১০ম শ্রেণির জীববিজ্ঞান বিষয়ের একটি পাওয়ার পয়েন্ট প্রেজেন্টেশন তৈরি করেন। তিনি স্লাইডসমূহ ঠিকঠাক মতো কাজ করে কিনা এবং যথাযথ হয়েছে কিনা তা পরীক্ষা করে নিতে চাইলেন।', 'dinajpur', 2023, true),
  ('ict-board-dinajpur-2023-mcq-003', 'class9-ict-bn-guide', 'satt-ict-board.pdf p39', 'উপরোক্ত অভ্যাস পরিহার করতে মিনার — i. বেশি বেশি বই পড়তে পারে ii. বাবা মাকে বেশি সময় দিতে পারে iii. ফেসবুকের বন্ধু দের সঙ্গে আড্ডা দিতে পারে নিচের কোনটি সঠিক ?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'ict-board-dinajpur-2023-mcq', false, 'board-mcq', null, 'মিনার সোশ্যাল সাইটে বেশ অ্যাকটিভ। তার অনেক বন্ধু রয়েছে। আইসিটি ক্লাসে স্যার সোশ্যাল সাইটের ক্ষতিকর দিকগুলোর কথা উল্লেখ করলে সে চিন্তিত হয়। তারপরও সে স্মার্টফোন ছাড়া থাকতে পারে না।', 'dinajpur', 2023, true),
  ('ict-board-dinajpur-2023-mcq-004', 'class9-ict-bn-guide', 'satt-ict-board.pdf p39', 'মিনারের যে সমস্যাটি হয়েছে, তাকে মনোবিজ্ঞানের ভাষায় কী বলা হয় ?', 'mcq', '{"ক":"Narcissism","খ":"Addiction","গ":"Egoism","ঘ":"Egotism"}'::jsonb, 'ক', 1, false, 'ict-board-dinajpur-2023-mcq', false, 'board-mcq', null, 'মিনার সোশ্যাল সাইটে বেশ অ্যাকটিভ। তার অনেক বন্ধু রয়েছে। আইসিটি ক্লাসে স্যার সোশ্যাল সাইটের ক্ষতিকর দিকগুলোর কথা উল্লেখ করলে সে চিন্তিত হয়। তারপরও সে স্মার্টফোন ছাড়া থাকতে পারে না।', 'dinajpur', 2023, true),
