  ('ict-board-jessore-2024-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p25', 'নিচের কোন পাসওয়ার্ডটি সহজে হ্যাক করা সম্ভব নয়?', 'mcq', '{"ক":"123456","খ":"Hossain","গ":"Aksa #2015Bsc","ঘ":"qwerty"}'::jsonb, 'গ', 1, false, 'ict-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
