  ('ict-board-jessore-2025-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p10', 'রেজা ও রীমার পিসিটির সর্বোত্তম ব্যবহার হবে-', 'mcq', '{"ক":"গেমস খেলায়","খ":"গান শোনায়","গ":"হিসাব নিকাশে","ঘ":"লেখাপড়ার কাজে"}'::jsonb, 'ঘ', 1, false, 'ict-board-jessore-2025-mcq', false, 'board-mcq', null, 'রেজা ও রীমার বাবা তাদের জন্য একটি ট্যাবলেট পিসি কিনে দিলেন। রেজা নবম শ্রেণিতে ও রীমা দ্বাদশ শ্রেণিতে পড়ে।', 'jessore', 2025, true),
  ('ict-board-jessore-2025-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p10', 'রেজা ও রীমার ট্যাবলেট পিসিটার সর্বোচ্চ ব্যবহার করতে - 1. দ্রুত গতির ইন্টারনেট সংযোগ প্রয়োজন ii. কম খরচে ইন্টারনেট ব্যবহারের সুযোগ দিতে হবে iii. ইংরেজি ভাষার দক্ষতা বাড়াতে হবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-jessore-2025-mcq', false, 'board-mcq', null, 'রেজা ও রীমার বাবা তাদের জন্য একটি ট্যাবলেট পিসি কিনে দিলেন। রেজা নবম শ্রেণিতে ও রীমা দ্বাদশ শ্রেণিতে পড়ে।', 'jessore', 2025, true),
